// Edit this list to steer discovery. One item per brief; the suggested queries guide Claude's web searches (Turkish and English).
const briefs = [
  { segment: 'Knitwear', brief: 'Turkish knitwear (örme) manufacturers exporting to EU brands', queries: ['Türkiye örme konfeksiyon ihracatçı firma Avrupa', 'Turkish knitwear manufacturer exporting to Europe EU brands', 'İHKİB örme hazır giyim ihracat ödülü firma listesi'] },
  { segment: 'Woven apparel', brief: 'Turkish woven apparel and shirt manufacturers producing for European retailers', queries: ['Türkiye dokuma gömlek üreticisi ihracat Avrupa', 'Turkish woven garment shirt manufacturer export Europe retailers', 'İHKİB dokuma konfeksiyon ihracat şampiyonları firma'] },
  { segment: 'Denim', brief: 'Turkish denim and jeans manufacturers supplying EU brands', queries: ['Türkiye denim jean üreticisi Avrupa ihracat', 'Turkish denim jeans manufacturer supplying European brands', 'Denim Première Vision Istanbul Turkish denim exhibitor'] },
  { segment: 'Home textile', brief: 'Turkish home textile exporters (towels, bedding) selling to the EU', queries: ['Denizli havlu bornoz ihracatçı firma Avrupa', 'Turkish home textile towel bedding manufacturer export Europe', 'Bursa ev tekstili ihracatçı üretici Avrupa'] },
  { segment: 'Fabric mill', brief: 'Turkish fabric mills with OEKO-TEX, GOTS or GRS certification exporting to Europe', queries: ['Türkiye kumaş üreticisi GOTS OEKO-TEX ihracat Avrupa', 'Turkish fabric mill GOTS GRS certified exporting to Europe', 'Texworld Paris Turkish fabric mill exhibitor'] },
  { segment: 'Sportswear', brief: 'Turkish sportswear and activewear manufacturers for EU brands', queries: ['Türkiye spor giyim activewear üreticisi ihracat Avrupa', 'Turkish sportswear activewear manufacturer for European brands', 'İzmir activewear manufacturer export EU'] },
];

const existing = $input.all().map(i => i.json).filter(r => r && (r['Company'] || r['Website']));
const knownNames = existing.map(r => String(r['Company'] || '').trim()).filter(Boolean);
const excludeText = knownNames.slice(0, 200).join('; ') || '(none)';
const runDate = new Date().toISOString().slice(0, 10);

return briefs.map((b, i) => ({ json: { brief_no: i + 1, segment: b.segment, brief: b.brief, queries_text: b.queries.map((q, k) => `${k + 1}. ${q}`).join('\n'), exclude: excludeText, run_date: runDate } }));

const minConfidence = 60;
const maxNewPerRun = 25;

function domainOf(url) {
  return String(url || '').toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').split('/')[0].split(':')[0].trim();
}
function norm(name) {
  return String(name || '').toLowerCase().replace(/\b(a\.?ş\.?|a\.?s\.?|ltd\.?|şti\.?|sti\.?|san\.?|tic\.?|ve|tekstil|textile|textiles|konfeksiyon)\b/g, ' ').replace(/[^a-z0-9çğıöşü]+/g, ' ').trim();
}

const existing = $('Get Existing Leads').all().map(i => i.json).filter(r => r && (r['Company'] || r['Website']));
const seenDomains = new Set(existing.map(r => domainOf(r['Website'])).filter(Boolean));
const seenNames = new Set(existing.map(r => norm(r['Company'])).filter(Boolean));
let maxId = 0;
for (const r of existing) {
  const m = /^L0*(\d+)$/i.exec(String(r['Lead ID'] || '').trim());
  if (m) maxId = Math.max(maxId, Number(m[1]));
}

const today = new Date().toISOString().slice(0, 10);
const out = [];
const skipped = { noSource: 0, lowConfidence: 0, duplicate: 0 };
for (const item of $input.all()) {
  const c = item.json || {};
  const domain = domainOf(c.website);
  const name = norm(c.company);
  if (!c.source_url || !domain || !name) { skipped.noSource++; continue; }
  if (Number(c.confidence || 0) < minConfidence) { skipped.lowConfidence++; continue; }
  if (seenDomains.has(domain) || seenNames.has(name)) { skipped.duplicate++; continue; }
  if (out.length >= maxNewPerRun) break;
  seenDomains.add(domain);
  seenNames.add(name);
  maxId++;
  out.push({ json: {
    'Lead ID': 'L' + String(maxId).padStart(3, '0'),
    'Company': String(c.company).trim(),
    'Website': String(c.website).trim(),
    'Country': 'Turkey',
    'Segment': String(c.segment || '').trim(),
    'Source URL': String(c.source_url).trim(),
    'Source Date': today,
    'Confidence': String(Math.round(Number(c.confidence))),
    'Research Notes': 'EU evidence: ' + String(c.eu_evidence || '').trim(),
    'Stage': 'New',
    'Last Updated': new Date().toISOString(),
    skipped_summary: JSON.stringify(skipped),
  } });
}
return out;

