// One item per company found, in the shape Dedupe expects. Replies without JSON are skipped. Input can come from the main Claude node or the account-2 fallback, so the segment comes from Claude's answer.
function strings(v, acc) {
  if (typeof v === 'string') acc.push(v);
  else if (Array.isArray(v)) v.forEach(x => strings(x, acc));
  else if (v && typeof v === 'object') Object.values(v).forEach(x => strings(x, acc));
  return acc;
}
function extract(text) {
  const s = text.indexOf('{'); const e = text.lastIndexOf('}');
  if (s < 0 || e <= s) return null;
  for (let end = e; end > s; end = text.lastIndexOf('}', end - 1)) {
    try { const o = JSON.parse(text.slice(s, end + 1)); if (o && Array.isArray(o.companies)) return o; } catch (err) { /* try a shorter slice */ }
  }
  return null;
}
const out = [];
$input.all().forEach((item) => {
  const body = item.json || {};
  const texts = strings(body, []).filter(t => t.includes('"companies"'));
  let parsed = null;
  for (const t of texts) { parsed = extract(t); if (parsed) break; }
  if (!parsed) return;
  for (const c of parsed.companies) {
    if (!c || typeof c !== 'object') continue;
    out.push({ json: {
      company: String(c.company || '').trim(),
      website: String(c.website || '').trim(),
      segment: String(c.segment || '').trim(),
      eu_evidence: String(c.eu_evidence || '').trim(),
      source_url: String(c.source_url || '').trim(),
      confidence: Number(c.confidence || 0),
    } });
  }
});
return out.filter(i => i.json.company && i.json.website);

